gcNE(){return"\u0645\u062f\u06cc\u0631\u06cc\u062a \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u0627\u062a\u0635\u0627\u0644 \u0645\u0648\u062f\u06cc\u0627\u0646"},
