gd42(){return"\u06a9\u0644\u06cc\u062f\u0647\u0627 \u0648 \u06af\u0648\u0627\u0647\u06cc\u200c\u0647\u0627"},
gd40(){return"\u06a9\u06cc\u0641\u06cc\u062a \u062f\u0627\u062f\u0647"},
gd41(){return"\u0631\u0627\u0647\u0646\u0645\u0627"},
