gd1o(){return"\u0627\u06cc\u0646 \u0631\u0627\u0647\u0646\u0645\u0627 \u062a\u0645\u0627\u0645 \u0645\u0631\u0627\u062d\u0644 \u0627\u062a\u0635\u0627\u0644 \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u0628\u0647 \u0633\u0627\u0645\u0627\u0646\u0647 \u0645\u0648\u062f\u06cc\u0627\u0646 \u062f\u0631 \u0646\u0633\u062e\u0647 \u062c\u062f\u06cc\u062f \u062d\u0633\u0627\u0628\u06cc\u06a9\u0633 \u0631\u0627 \u0645\u0631\u0648\u0631 \u0645\u06cc\u200c\u06a9\u0646\u062f\u061b \u0627\u0632 \u062a\u0648\u0644\u06cc\u062f \u06a9\u0644\u06cc\u062f\u0647\u0627 \u062a\u0627 \u06a9\u0646\u062a\u0631\u0644 \u06a9\u06cc\u0641\u06cc\u062a \u062f\u0627\u062f\u0647 \u0648 \u0627\u0631\u0633\u0627\u0644 \u0635\u0648\u0631\u062a\u062d\u0633\u0627\u0628."},
gd1t(){return"\u067e\u06cc\u0634\u200c\u0646\u06cc\u0627\u0632\u0647\u0627\u06cc \u0642\u0628\u0644 \u0627\u0632 \u0634\u0631\u0648\u0639"},
gd1q(){return"\u062f\u0633\u062a\u0631\u0633\u06cc \u06a9\u0627\u0631\u0628\u0631 \u0627\u0635\u0644\u06cc \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u0628\u0647 \u0645\u0646\u0648\u06cc \xab\u0633\u0627\u0645\u0627\u0646\u0647 \u0645\u0648\u062f\u06cc\u0627\u0646\xbb \u062f\u0631 \u062d\u0633\u0627\u0628\u06cc\u06a9\u0633"},
gd1r(){return"\u0627\u0637\u0644\u0627\u0639\u0627\u062a \u062b\u0628\u062a\u06cc \u0635\u062d\u06cc\u062d (\u0634\u0646\u0627\u0633\u0647 \u0645\u0644\u06cc\u060c \u06a9\u062f \u0627\u0642\u062a\u0635\u0627\u062f\u06cc \u0648 \u0627\u06cc\u0645\u06cc\u0644 \u0633\u0627\u0632\u0645\u0627\u0646\u06cc \u0645\u0639\u062a\u0628\u0631)"},
