gd1D(){return"\u0641\u0627\u06cc\u0644\u200c\u0647\u0627\u06cc \u06a9\u0644\u06cc\u062f \u0631\u0627 \u062f\u0627\u0646\u0644\u0648\u062f \u0648 \u062f\u0631 \u0641\u0636\u0627\u06cc \u0622\u0641\u0644\u0627\u06cc\u0646 (USB \u06cc\u0627 \u0631\u0645\u0632\u062f\u0627\u0631) \u0646\u06af\u0647\u062f\u0627\u0631\u06cc \u06a9\u0646\u06cc\u062f."},
gd1E(){return"\u0627\u0632 \u0627\u0634\u062a\u0631\u0627\u06a9\u200c\u06af\u0630\u0627\u0631\u06cc \u06a9\u0644\u06cc\u062f \u062e\u0635\u0648\u0635\u06cc \u0628\u0627 \u0627\u0641\u0631\u0627\u062f \u063a\u06cc\u0631\u0645\u0633\u0626\u0648\u0644 \u062e\u0648\u062f\u062f\u0627\u0631\u06cc \u06a9\u0646\u06cc\u062f."},
gd1F(){return"\u062f\u0631 \u0635\u0648\u0631\u062a \u0645\u0641\u0642\u0648\u062f\u06cc \u06a9\u0644\u06cc\u062f \u062e\u0635\u0648\u0635\u06cc \u0628\u0627\u06cc\u062f \u0641\u0631\u0622\u06cc\u0646\u062f \u062a\u0648\u0644\u06cc\u062f \u06a9\u0644\u06cc\u062f \u0631\u0627 \u0627\u0632 \u0627\u0628\u062a\u062f\u0627 \u0637\u06cc \u06a9\u0646\u06cc\u062f."},
gd1M(){return"\u06f3) \u062b\u0628\u062a \u06a9\u0644\u06cc\u062f \u0639\u0645\u0648\u0645\u06cc \u062f\u0631 \u0633\u0627\u0645\u0627\u0646\u0647 \u0645\u0648\u062f\u06cc\u0627\u0646"},
gd1L(){return"\u0628\u0631\u0627\u06cc \u062f\u0631\u06cc\u0627\u0641\u062a \u0634\u0646\u0627\u0633\u0647 \u06cc\u06a9\u062a\u0627\u06cc \u062d\u0627\u0641\u0638\u0647 \u0628\u0627\u06cc\u062f Public Key \u0631\u0627 \u062f\u0631 \u06a9\u0627\u0631\u067e\u0648\u0634\u0647 \u0645\u0627\u0644\u06cc\u0627\u062a\u06cc \u062b\u0628\u062a \u06a9\u0646\u06cc\u062f."},
gd1I(){return"\u0628\u0647 my.tax.gov.ir \u0648\u0627\u0631\u062f \u0634\u0648\u06cc\u062f \u0648 \u0645\u0633\u06cc\u0631 \xab\u0648\u0631\u0648\u062f \u0628\u0647 \u067e\u0631\u0648\u0646\u062f\u0647 > \u0639\u0636\u0648\u06cc\u062a > \u0634\u0646\u0627\u0633\u0647 \u06cc\u06a9\u062a\u0627 \u062d\u0627\u0641\u0638\u0647 \u0645\u0627\u0644\u06cc\u0627\u062a\u06cc\xbb \u0631\u0627 \u062f\u0646\u0628\u0627\u0644 \u06a9\u0646\u06cc\u062f."},
gd1J(){return"\u06af\u0632\u06cc\u0646\u0647 \xab\u062a\u0648\u0633\u0637 \u0645\u0648\u062f\u06cc\xbb \u0631\u0627 \u0627\u0646\u062a\u062e\u0627\u0628 \u0648 \u0641\u0627\u06cc\u0644 Public Key \u0631\u0627 \u0628\u0627\u0631\u06af\u0630\u0627\u0631\u06cc \u06a9\u0646\u06cc\u062f."},
gd1K(){return"\u0634\u0646\u0627\u0633\u0647 \u06cc\u06a9\u062a\u0627\u06cc \u0646\u0645\u0627\u06cc\u0634 \u062f\u0627\u062f\u0647 \u0634\u062f\u0647 \u0631\u0627 \u0630\u062e\u06cc\u0631\u0647 \u0648 \u062f\u0631 \u062d\u0633\u0627\u0628\u06cc\u06a9\u0633 \u0648\u0627\u0631\u062f \u06a9\u0646\u06cc\u062f."},
gd1R(){return"\u06f4) \u062a\u06a9\u0645\u06cc\u0644 \u0641\u0631\u0645 \u0627\u062a\u0635\u0627\u0644 \u062f\u0631 \u062d\u0633\u0627\u0628\u06cc\u06a9\u0633"},
gd1Q(){return"\u0634\u0646\u0627\u0633\u0647 \u062d\u0627\u0641\u0638\u0647\u060c \u06a9\u062f \u0627\u0642\u062a\u0635\u0627\u062f\u06cc \u0648 \u06a9\u0644\u06cc\u062f \u062e\u0635\u0648\u0635\u06cc \u0628\u0627\u06cc\u062f \u062f\u0631 \u062a\u0628 \xab\u0627\u062a\u0635\u0627\u0644 \u0648 \u0627\u0637\u0644\u0627\u0639\u0627\u062a \u067e\u0627\u06cc\u0647\xbb \u062b\u0628\u062a \u0634\u0648\u0646\u062f."},
gd1N(){return"\u0634\u0646\u0627\u0633\u0647 \u06cc\u06a9\u062a\u0627 \u0648 \u06a9\u062f \u0627\u0642\u062a\u0635\u0627\u062f\u06cc \u0631\u0627 \u0628\u062f\u0648\u0646 \u0641\u0627\u0635\u0644\u0647 \u0627\u0636\u0627\u0641\u06cc \u0648\u0627\u0631\u062f \u06a9\u0646\u06cc\u062f."},
gd1O(){return"\u0628\u0627 \xab\u062a\u0648\u0644\u06cc\u062f \u06a9\u0644\u06cc\u062f \u062c\u062f\u06cc\u062f\xbb\u060c \u06a9\u0644\u06cc\u062f \u062e\u0635\u0648\u0635\u06cc\u060c \u06a9\u0644\u06cc\u062f \u0639\u0645\u0648\u0645\u06cc \u0648 CSR \u0633\u0627\u062e\u062a\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f\u061b CSR \u0631\u0627 \u062f\u0631 \u0645\u0631\u06a9\u0632 \u0645\u06cc\u0627\u0646\u06cc \u062b\u0628\u062a \u0648 \u06af\u0648\u0627\u0647\u06cc (.crt) \u0631\u0627 \u067e\u0633 \u0627\u0632 \u0635\u062f\u0648\u0631 \u062f\u0631 \u0647\u0645\u06cc\u0646 \u0635\u0641\u062d\u0647 \u0630\u062e\u06cc\u0631\u0647 \u06a9\u0646\u06cc\u062f."},
gd1P(){return"\u062f\u0631 \u0635\u0648\u0631\u062a \u0627\u0633\u062a\u0641\u0627\u062f\u0647 \u0627\u0632 \u0645\u062d\u06cc\u0637 \u062a\u0633\u062a\u060c \u06af\u0632\u06cc\u0646\u0647 \u062d\u0627\u0644\u062a \u0633\u0646\u062f\u0628\u0627\u06a9\u0633 \u0631\u0627 \u0641\u0639\u0627\u0644 \u06a9\u0646\u06cc\u062f."},
