gcFJ(){return"\u067e\u0633 \u0627\u0632 \u067e\u0634\u062a\u06cc\u0628\u0627\u0646\u200c\u06af\u06cc\u0631\u06cc\u060c \u0628\u0631\u06af\u0634\u062a \u0627\u0632 \u0633\u0627\u0644 \u0645\u0627\u0644\u06cc \u062f\u06cc\u06af\u0631 \u0645\u062c\u0627\u0632 \u0646\u06cc\u0633\u062a. \u0627\u062d\u062a\u0645\u0627\u0644\u0627\u064b \u0648\u0636\u0639\u06cc\u062a \u06a9\u0633\u0628\u200c\u0648\u06a9\u0627\u0631 \u062a\u063a\u06cc\u06cc\u0631 \u06a9\u0631\u062f\u0647. \u067e\u06cc\u0634\u200c\u0646\u0645\u0627\u06cc\u0634 \u0631\u0627 \u0628\u0631\u0631\u0633\u06cc \u0648 \u062f\u0648\u0628\u0627\u0631\u0647 \u062a\u0644\u0627\u0634 \u06a9\u0646\u06cc\u062f."},
gcGc(){return"\u06a9\u062f \u062a\u0623\u06cc\u06cc\u062f \u067e\u0633 \u0627\u0632 \u067e\u0634\u062a\u06cc\u0628\u0627\u0646 \u062f\u0631\u06cc\u0627\u0641\u062a \u0646\u0634\u062f. \xab\u0628\u0647\u200c\u0631\u0648\u0632\u0631\u0633\u0627\u0646\u06cc \u067e\u06cc\u0634\u200c\u0646\u0645\u0627\u06cc\u0634\xbb \u0631\u0627 \u0628\u0632\u0646\u06cc\u062f."},
gcGe(){return"\u06a9\u062f \u062a\u0623\u06cc\u06cc\u062f \u062f\u0631 \u062f\u0633\u062a\u0631\u0633 \u0646\u06cc\u0633\u062a."},
gcG5(){return"\u062f\u0631 \u062d\u0627\u0644 \u062d\u0630\u0641 \u0633\u0627\u0644 \u0645\u0627\u0644\u06cc \u062c\u0627\u0631\u06cc\u2026"},
gcGa(){return"\u0628\u0627 \u0645\u0648\u0641\u0642\u06cc\u062a \u0627\u0646\u062c\u0627\u0645 \u0634\u062f"},
gcGf(){return"\u0627\u06cc\u0646 \u0639\u0645\u0644\u06cc\u0627\u062a \u062a\u0645\u0627\u0645 \u0627\u0633\u0646\u0627\u062f \u0633\u0627\u0644 \u0645\u0627\u0644\u06cc \u062c\u0627\u0631\u06cc \u0631\u0627 \u062d\u0630\u0641 \u0645\u06cc\u200c\u06a9\u0646\u062f \u0648 \u0633\u0627\u0644 \u0642\u0628\u0644 \u0631\u0627 \u062f\u0648\u0628\u0627\u0631\u0647 \xab\u062c\u0627\u0631\u06cc\xbb \u0645\u06cc\u200c\u06a9\u0646\u062f."},
gcFX(){return"\u0633\u0627\u0644 \u062c\u0627\u0631\u06cc (\u062d\u0630\u0641 \u0645\u06cc\u200c\u0634\u0648\u062f)"},
bpM(a){return"\u0634\u0646\u0627\u0633\u0647 "+a},
gcG2(){return"\u0633\u0627\u0644 \u0628\u0639\u062f\u06cc \u062c\u0627\u0631\u06cc"},
cFY(a){return"\u062a\u0639\u062f\u0627\u062f \u0627\u0633\u0646\u0627\u062f \u0633\u0627\u0644 \u062c\u0627\u0631\u06cc: "+a},
cFS(a){return"\u0627\u0633\u0646\u0627\u062f \u0628\u0633\u062a\u0646 \u0633\u0627\u0644 \u0631\u0648\u06cc \u0633\u0627\u0644 \u0642\u0628\u0644 \u06a9\u0647 \u062d\u0630\u0641 \u0645\u06cc\u200c\u0634\u0648\u0646\u062f: "+a},
gcFL(){return"\u0642\u0628\u0644 \u0627\u0632 \u062d\u0630\u0641 \u0633\u0627\u0644\u060c \u067e\u0634\u062a\u06cc\u0628\u0627\u0646 \u06a9\u0627\u0645\u0644 \u0628\u06af\u06cc\u0631\u0645"},
gcFK(){return"\u0647\u0645\u0627\u0646 \u067e\u0634\u062a\u06cc\u0628\u0627\u0646 \u0633\u06cc\u0633\u062a\u0645\u06cc (.hbx) \u0627\u0632 \u0628\u062e\u0634 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a\u061b \u0628\u0631\u0627\u06cc \u0628\u0627\u0632\u06cc\u0627\u0628\u06cc \u062f\u0631 \u0635\u0648\u0631\u062a \u0646\u06cc\u0627\u0632."},
gcG3(){return"\u0628\u0627\u0632 \u06a9\u0631\u062f\u0646 \u0635\u0641\u062d\u0647\u0654 \u067e\u0634\u062a\u06cc\u0628\u0627\u0646\u200c\u06af\u06cc\u0631\u06cc"},
gcFZ(){return"\u0627\u062c\u0631\u0627\u06cc \u062d\u0630\u0641 \u0633\u0627\u0644 \u0645\u0627\u0644\u06cc \u062c\u0627\u0631\u06cc"},
gcFQ(){return"\u0627\u06cc\u0646 \u0639\u0645\u0644\u06cc\u0627\u062a \u0627\u0644\u0627\u0646 \u0645\u062c\u0627\u0632 \u0646\u06cc\u0633\u062a \u2014 \u062f\u0644\u0627\u06cc\u0644:"},
gcFP(){return"\u067e\u0633 \u0627\u0632 \u0631\u0641\u0639 \u0645\u0648\u0627\u0631\u062f \u0632\u06cc\u0631\u060c \u062f\u06a9\u0645\u0647\u0654 \xab\u0628\u0647\u200c\u0631\u0648\u0632\u0631\u0633\u0627\u0646\u06cc \u067e\u06cc\u0634\u200c\u0646\u0645\u0627\u06cc\u0634\xbb \u0631\u0627 \u0628\u0632\u0646\u06cc\u062f."},
gcG8(){return"\u0628\u0647\u200c\u0631\u0648\u0632\u0631\u0633\u0627\u0646\u06cc \u067e\u06cc\u0634\u200c\u0646\u0645\u0627\u06cc\u0634"},
cFN(a){return"\u067e\u0634\u062a\u06cc\u0628\u0627\u0646: "+a},
gcG7(){return"\u067e\u06cc\u0634\u200c\u0646\u0645\u0627\u06cc\u0634 \u0628\u0631\u06af\u0634\u062a \u0627\u0632 \u0633\u0627\u0644 \u0645\u0627\u0644\u06cc \u0646\u0627\u0645\u0648\u0641\u0642 \u0628\u0648\u062f."},
